const cfg=$('Configuração Maintenance').first().json;
  const projects=$input.first().json.payloads??[];
  if(projects.length===0) return [{json:{kind:'empty',action:'skipped',reason:'no-projects'}}];
  return projects.map(project=>({json:{
    ...project,
    documentationMode:'maintenance',
    maintenanceContext:{config:cfg}
  }}));

const project=$('Loop por projeto').item.json;
  const cfg=project.maintenanceContext?.config??$('Configuração Maintenance').first().json;
  let remoteManifest=null;
  if(typeof $json.content==='string'){
    try{
      const text=Buffer.from($json.content.replace(/\s/g,''),'base64').toString('utf8');
      remoteManifest=JSON.parse(text);
    }catch{remoteManifest=null;}
  }
  const needsBootstrap=!remoteManifest?.bootstrapCompleted;
  const changed=!needsBootstrap&&remoteManifest.functionalHash!==project.functionalHash;
  const aiMode=String(remoteManifest?.aiMode??project.aiMode??'bootstrap');
  return {json:{
    ...project,
    aiMode,
    documentationMode:'maintenance',
    maintenanceContext:{
      config:cfg,
      remoteManifest,
      needsBootstrap,
      changed
    }
  }};

const input=$input.first().json;
  const project=Array.isArray(input.payloads)?input.payloads[0]:input;
  const context=project.maintenanceContext??{};
  const cfg=context.config??$('Configuração Maintenance').first().json;
  const remote=context.remoteManifest??{};
  const generated=JSON.parse(project.technicalFiles?.['project.json']??'{}');
  const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'})
    .format(new Date()).replace(/-/g,'.');
  const current=String(remote.currentVersion??'');
  const match=current.match(new RegExp('^'+today.replace(/\./g,'\\.')+'\\.(\\d+)$'));
  const sequence=match?Number(match[1])+1:1;
  const version=today+'.'+sequence;
  const updatedManifest={
    ...generated,
    bootstrapCompleted:true,
    sourceOfTruth:'github',
    aiMode:String(remote.aiMode??project.aiMode??'bootstrap'),
    documentationLayout:String(remote.documentationLayout??'legacy'),
    documentationSchemaVersion:Number(remote.documentationSchemaVersion??1),
    currentVersion:version,
    previousFunctionalHash:remote.functionalHash??null,
    lastMaintenanceAt:new Date().toISOString(),
    reviewRequired:true
  };
  const technicalFiles={...(project.technicalFiles??{})};
  delete technicalFiles['project.json'];
  const relativeFiles={
    ...technicalFiles,
    'project.json':JSON.stringify(updatedManifest,null,2)
  };
  const files=Object.fromEntries(Object.entries(relativeFiles).map(([file,content])=>[
    'projects/'+project.projectSlug+'/'+file,content
  ]));
  return [{json:{
    owner:cfg.owner,
    repository:cfg.repository,
    branch:cfg.branch,
    projectSlug:project.projectSlug,
    version,
    functionalHash:project.functionalHash,
    files,
    commitMessage:'docs('+project.projectSlug+'): maintenance '+version
  }}];

const prepared=$('Preparar publicação técnica').item.json;
  return {json:{
    action:'updated',
    projectSlug:prepared.projectSlug,
    version:prepared.version,
    functionalHash:prepared.functionalHash,
    publication:$json
  }};

const context=$json.maintenanceContext??{};
  return {json:{
    action:context.needsBootstrap?'needs-bootstrap':'skipped',
    projectSlug:$json.projectSlug,
    previousHash:context.remoteManifest?.functionalHash??null,
    currentHash:$json.functionalHash,
    reason:context.needsBootstrap?'Execute o Bootstrap primeiro.':'Hash funcional sem alteração.'
  }};

const rows=$input.all().map(item=>item.json);
  return [{json:{
    status:'maintenance-complete',
    checkedProjects:rows.length,
    updated:rows.filter(row=>row.action==='updated').length,
    skipped:rows.filter(row=>row.action==='skipped').length,
    needsBootstrap:rows.filter(row=>row.action==='needs-bootstrap').length,
    projects:rows,
    reviewRequired:true
  }}];
